      DOC.rows=filterRows(documentRows(),range);DOC.applied=true;
      $('#ucV9StatementGrid').innerHTML=statementTable(DOC.rows);const paidTotal=DOC.rows.reduce((sum,r)=>sum+(String(r.payment_status||'').toLowerCase()==='paid'?Number(r.amount_received_paise||0):0),0),pendingTotal=DOC.rows.reduce((sum,r)=>sum+(String(r.payment_status||'').toLowerCase()==='pending'?Number(r.pending_amount_paise||r.balance_amount_paise||r.total_order_amount_paise||0):0),0);
      $('#ucV9StatementSummary').innerHTML=`<span>${H(displayDate(range.from))} to ${H(displayDate(range.to))} • ${DOC.rows.length} record(s)</span><strong>${paidTotal?`Paid ${H(moneyPaise(paidTotal))}`:''}${paidTotal&&pendingTotal?' • ':''}${pendingTotal?`Pending ${H(moneyPaise(pendingTotal))}`:''}${!paidTotal&&!pendingTotal?'No payment amount':''}</strong>`;
      const c=client();$('#ucV9StatementDownload').disabled=false;$('#ucV9StatementWhatsapp').disabled=!c.phone;$('#ucV9StatementEmail').disabled=!c.email;
