        y+=22;roundRect(ctx,margin,y,W-margin*2,116,8,'#ffffff','#d9c8bf');ctx.textAlign='center';ctx.fillStyle=primary;ctx.font='bold 21px Arial';ctx.fillText(`Thank you for choosing ${brandName()}.`,W/2,y+38);ctx.fillStyle='#51414a';ctx.font='16px Arial';ctx.fillText(pendingTotal?'Pending entries indicate a payment request exists but money has not yet been confirmed as received.':'All amounts marked Paid are supported by a successful payment record.',W/2,y+75);ctx.textAlign='left';
