    $$('.nav button,[data-tab="settings"]').forEach(b=>{if(b.dataset.tab==='settings'||/Site Settings|Front-end Settings/.test(b.textContent||''))if(b.textContent!=='Brand Settings')b.textContent='Brand Settings';});
