  function patchSmallUi(){const maps=$('#mapsReviews');if(maps){$$('button',maps).forEach(b=>{if(/^\+\s*Add\s*Location$/i.test((b.textContent||'').trim())){b.textContent='+ Location';b.classList.add('uc-v10-location-btn');}});}const about=$('#pages .uc-v7-about-media,#pages .uc-v7-about-cover-card,#pages .uc-about-cover-card,#pages [data-about-cover]');if(about)about.classList.add('uc-v10-about-cover');const label=$('#pages input[data-page-field="cover_image_url"],#pages input[name="about_cover_url"],#pages input[name="cover_image_url"]');if(label){const box=label.closest('.uc-v7-about-media,.card,.field')||label.parentElement;if(box)box.classList.add('uc-v10-about-cover');}}

